import { expect, it } from 'vitest'
import { CONTROL_SPECULAR, CONTROL_RIM_LOW_LUMA_GAIN, controlRimUniform, controlSizeResponse, controlShadowScale } from './controlRim.ts'
import { shaders } from './shaders.ts'

// Independent optical reference: a colour-transform layer over an opaque flat backdrop.
// These samples are native screenshot pixels, not values generated by the shader.
function rimPixel(appearance: 'light' | 'dark', background: number, outsidePt: number, nx: number) {
  const [support, opacity, darkAppearance, vertical] = controlRimUniform(appearance)
  const b = background / 255
  const alpha = Math.min(1, (opacity + CONTROL_RIM_LOW_LUMA_GAIN * Math.max(0.5 - b, 0)) * Math.max(0, 1 - outsidePt / support) * (nx * nx + vertical * (1 - nx * nx)))
  const light = Math.max(0, b * (b - 0.5))
  const dark = 0.6 * Math.max(b - 0.5, 0) * (1 - b)
  const colour = (light * (1 - darkAppearance) + dark * darkAppearance) * 255
  return colour * alpha + background * (1 - alpha)
}

it('reproduces native exterior cardinal samples across appearance and backdrop', () => {
  for (const [appearance, background, near, far] of [
    ['light', 32, 6, 19],
    ['light', 64, 17, 40],
    ['light', 96, 32, 64],
    ['light', 128, 52, 90],
    ['dark', 32, 6, 19],
    ['dark', 64, 16, 40],
    ['dark', 96, 32, 64],
    ['dark', 128, 52, 90],
    ['dark', 159, 69, 113],
    ['dark', 191, 82, 135],
    ['light', 255, 176, 215],
    ['dark', 255, 100, 178],
  ] as const) {
    expect(Math.abs(rimPixel(appearance, background, 1 / 6, 1) - near)).toBeLessThan(3)
    expect(Math.abs(rimPixel(appearance, background, 0.5, 1) - far)).toBeLessThan(3)
  }
})

it('does not invent a black-room outline or a left/right light source', () => {
  for (const appearance of ['light', 'dark'] as const)
    for (const nx of [0, 0.25, 0.5, 1]) {
      expect(rimPixel(appearance, 0, 0.5, nx)).toBe(0)
      expect(rimPixel(appearance, 192, 0.5, nx)).toBe(rimPixel(appearance, 192, 0.5, -nx))
    }
  expect(rimPixel('dark', 128, 0.5, 0)).toBe(128)
  expect(Math.abs(rimPixel('light', 128, 0.5, 0) - 114)).toBeLessThan(2)
})

it('matches the native bright-lobe contrast in both black-room appearances', () => {
  const [support, amount, diffuseSupport, diffuseAmount] = CONTROL_SPECULAR
  const h = amount * (1 - 0.5 / support) + diffuseAmount * (1 - 0.5 / diffuseSupport)
  // Native at half a point inside: light 162 above interior 130, dark 73 above 31.
  for (const [interior, peak] of [[130, 162], [31, 73]] as const)
    expect(Math.abs(interior + h * (37.5105 - 0.0882 * interior) - peak)).toBeLessThan(3)
})

it('wires the measured model to the active bar kernel and leaves menu optics separate', () => {
  expect(shaders.bar.wgsl).toContain('H = controlSpecular(signedPt_7, n_9)')
  expect(shaders.bar.wgsl).toContain('normal.x * normal.x')
  expect(shaders.bar.wgsl).not.toContain('contour = dot(')
  expect(shaders.menu.wgsl).not.toContain('controlSpecular')
})

it('matches the independent native size sweep without using corner radius', () => {
  for (const [height, white, grey, grey75] of [[44, 185, 134, 165], [64, 185, 134, 165], [80, 159, 127, 151], [100, 128, 119, 133]]) {
    const amount = controlSizeResponse('dark', 120, height) * 255
    for (const [background, original, measured] of [[1, 185, white], [0.5, 134, grey], [0.75, 165, grey75]])
      expect(Math.abs(original - amount * background ** 2 - measured)).toBeLessThan(1.5)
    expect(controlSizeResponse('light', 120, height)).toBe(0)
    expect(controlSizeResponse('dark', height, 120)).toBe(controlSizeResponse('dark', 120, height))
  }
})

it('matches native broad exterior shadow independently of the narrow rim', () => {
  for (const [appearance, height, native] of [['light', 44, 252], ['dark', 62, 252], ['light', 80, 248], ['dark', 80, 246]] as const) {
    const predicted = 255 - 10 * controlShadowScale(appearance, 120, height)
    expect(Math.abs(predicted - native)).toBeLessThan(1)
  }
})
